from pathlib import Path
import subprocess

ROOT=Path(__file__).resolve().parent
UPDATER=ROOT/"updater.py"
BASE_COMMIT="bb074274361bc6899e16bc340d3bceb56f787580"

def fetch_full():
    subprocess.run(["git","fetch","origin",BASE_COMMIT,"--depth=1"],cwd=ROOT,check=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
    r=subprocess.run(["git","show",f"{BASE_COMMIT}:updater.py"],cwd=ROOT,check=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
    src=r.stdout
    if len(src)<228000: raise RuntimeError(f"verified v15 updater unexpectedly small: {len(src)}")
    return src

def replace_between(src,start_marker,end_marker,replacement,label):
    a=src.find(start_marker)
    if a<0: raise RuntimeError(f"{label}: start marker not found")
    b=src.find(end_marker,a)
    if b<0: raise RuntimeError(f"{label}: end marker not found")
    return src[:a]+replacement+src[b:]

ENGINE='def _analyst_thesis_terms_v16():\n    return [\n        "demand","pricing","pricing power","contract pricing","margin","margins",\n        "revenue","sales","orders","backlog","growth","adoption","customer",\n        "customers","market share","capex","capacity","visibility","valuation",\n        "earnings","eps","cash flow","ai","artificial intelligence","cloud",\n        "data center","datacenter","product mix","launch","pipeline","deliveries",\n        "cost savings","execution","undersupply","supply","inventory",\n        "utilization","bookings","compute","premium rates","monetize"\n    ]\n\n\ndef _has_real_thesis_v16(text):\n    low=(text or "").lower()\n    return any(k in low for k in _analyst_thesis_terms_v16())\n\n\ndef _mechanical_only_v16(text):\n    s=re.sub(r"\\s+"," ",text or "").strip()\n    if not s:\n        return True\n    low=s.lower()\n\n    # A sentence that only states the rating/PT action is not a rationale.\n    mechanical=bool(re.search(\n        r"\\b(?:maintain(?:s|ed)?|reiterate(?:s|d)?|upgrade(?:s|d)?|downgrade(?:s|d)?|"\n        r"initiat(?:e|es|ed)|raise(?:s|d)?|cut(?:s)?|lower(?:s|ed)?|boost(?:s|ed)?)\\b",\n        low\n    ))\n    rating=bool(re.search(\n        r"\\b(?:strong buy|buy|outperform|overweight|neutral|equal[- ]weight|hold|"\n        r"market perform|underperform|underweight|sell)\\b",\n        low\n    ))\n    target=bool(re.search(r"\\b(?:price target|target price|target)\\b|\\$[\\d,.]+",low))\n\n    if (mechanical or rating or target) and not _has_real_thesis_v16(s):\n        return True\n\n    # Generic event labels are not a thesis.\n    generic=[\n        "project update","company update","stock update","quarterly update",\n        "pricing update","ahead of earnings","ahead of q3 deliveries",\n        "ahead of q4 results"\n    ]\n    if any(low==g or low.endswith(g) for g in generic):\n        return True\n    return False\n\n\ndef _candidate_fragments_v16(sentence):\n    s=re.sub(r"\\s+"," ",sentence or "").strip()\n    if not s:\n        return []\n\n    out=[s]\n    # Pull the actual explanatory clause out of a mixed sentence.\n    patterns=[\n        r"\\barguing that\\s+(.+)$",\n        r"\\bnoting that\\s+(.+)$",\n        r"\\bsaid that\\s+(.+)$",\n        r"\\bsays that\\s+(.+)$",\n        r"\\bbelieves? that\\s+(.+)$",\n        r"\\bexpects? that\\s+(.+)$",\n        r"\\bciting\\s+(.+)$",\n        r"\\bdue to\\s+(.+)$",\n        r"\\bbecause of\\s+(.+)$",\n        r"\\bdriven by\\s+(.+)$",\n        r"\\bsupported by\\s+(.+)$",\n        r"\\bon the back of\\s+(.+)$",\n        r"\\bon\\s+(.+?(?:growth|demand|pricing|margins?|revenue|orders?|backlog|ai|cloud|adoption|visibility|valuation|undersupply).*)$",\n        r"\\bafter\\s+(.+?(?:launch|results?|earnings|guidance|outlook).*)$",\n    ]\n    for pat in patterns:\n        m=re.search(pat,s,re.I)\n        if m:\n            frag=m.group(1).strip(" ,:;–—-")\n            if len(frag)>=8:\n                out.append(frag)\n\n    # Also consider comma/semicolon clauses independently. This fixes sentences\n    # such as: "shares rose..., after JPMorgan upgraded..., arguing that strong demand..."\n    for frag in re.split(r"\\s*[;]\\s*|\\s*,\\s+(?=(?:arguing|noting|citing|because|due|driven|supported|as|while)\\b)",s,flags=re.I):\n        frag=frag.strip(" ,:;–—-")\n        if len(frag)>=8:\n            out.append(frag)\n\n    dedup=[]\n    seen=set()\n    for x in out:\n        key=x.lower()\n        if key not in seen:\n            seen.add(key)\n            dedup.append(x)\n    return dedup\n\n\ndef _analyst_reason_score_v16(fragment, broker="", sentence_idx=0, broker_idx=None):\n    s=re.sub(r"\\s+"," ",fragment or "").strip()\n    if not s:\n        return -999\n    low=s.lower()\n    score=0\n\n    thesis_hits=sum(1 for k in _analyst_thesis_terms_v16() if k in low)\n    score += thesis_hits*3\n\n    if re.search(\n        r"\\b(?:arguing that|noting that|because|citing|due to|driven by|supported by|"\n        r"on the back of|believes? that|expects? that|said that|says that)\\b",low\n    ):\n        score += 7\n\n    if re.search(r"\\b(?:could|should|will|expected to|likely to)\\b",low) and thesis_hits:\n        score += 2\n\n    if broker and broker.lower() in low:\n        score += 2\n    if broker_idx is not None:\n        dist=abs(sentence_idx-broker_idx)\n        if dist==0:\n            score += 3\n        elif dist==1:\n            score += 2\n        elif dist==2:\n            score += 1\n\n    # Penalize market-performance/background language, but do not destroy a\n    # valid thesis clause that happens to share the same sentence.\n    background=[\n        "past 12 months","last 12 months","year to date","year-to-date",\n        "shares rose","shares fell","stock rose","stock fell","stock gained",\n        "stock dropped","market capitalization","market cap","52-week high",\n        "52-week low","trading at","closed at"\n    ]\n    if any(k in low for k in background):\n        score -= 7\n\n    if any(k in low for k in [\n        "investing.com","subscribe","newsletter","cookie","privacy policy",\n        "read more","advertisement","premium","copyright"\n    ]):\n        score -= 5\n\n    # Pure rating/target statements are never a reason, regardless of score.\n    if _mechanical_only_v16(s):\n        return -50\n\n    if len(s.split())<4:\n        score -= 3\n    return score\n\n\ndef _clean_reason_text_v16(text):\n    s=re.sub(r"\\s+"," ",text or "").strip(" ,:;–—-")\n    if not s or _mechanical_only_v16(s):\n        return ""\n\n    s=re.sub(\n        r"\\s+(?:By\\s+)?(?:Investing\\.com|Reuters|Bloomberg|MarketWatch|Barron\'?s|CNBC|Yahoo Finance)\\s*$",\n        "",\n        s,\n        flags=re.I\n    ).strip(" ,:;–—-")\n\n    # Remove leading attribution so the UI shows the thesis, not a repeated\n    # "JPMorgan upgraded..." sentence.\n    for pat in [\n        r"^.*?\\barguing that\\s+(.+)$",\n        r"^.*?\\bnoting that\\s+(.+)$",\n        r"^.*?\\bciting\\s+(.+)$",\n        r"^.*?\\bdue to\\s+(.+)$",\n        r"^.*?\\bbecause of\\s+(.+)$",\n        r"^.*?\\bdriven by\\s+(.+)$",\n        r"^.*?\\bsupported by\\s+(.+)$",\n        r"^.*?\\bon the back of\\s+(.+)$",\n    ]:\n        m=re.search(pat,s,re.I)\n        if m:\n            candidate=m.group(1).strip(" ,:;–—-")\n            if len(candidate)>=8:\n                s=candidate\n                break\n\n    if _mechanical_only_v16(s):\n        return ""\n    return s[:420]\n\n\ndef _best_analyst_reason_v16(text, broker=""):\n    src=re.sub(r"\\s+"," ",text or "").strip()\n    if not src:\n        return "",""\n\n    sents=[s.strip() for s in re.split(r"(?<=[.!?])\\s+|[\\u2022•]\\s*",src) if s.strip()]\n    if not sents:\n        return "",""\n\n    broker_idx=None\n    if broker:\n        for i,s in enumerate(sents):\n            if broker.lower() in s.lower():\n                broker_idx=i\n                break\n\n    scored=[]\n    for i,s in enumerate(sents):\n        for frag in _candidate_fragments_v16(s):\n            score=_analyst_reason_score_v16(frag,broker,i,broker_idx)\n            if score>-50:\n                scored.append((score,i,len(frag),frag))\n\n    scored.sort(reverse=True,key=lambda x:(x[0],-x[2]))\n    if not scored or scored[0][0] < 7:\n        return "",""\n\n    best_score,_,_,best=scored[0]\n    cleaned=_clean_reason_text_v16(best)\n    if not cleaned or not _has_real_thesis_v16(cleaned):\n        return "",""\n\n    confidence="high" if best_score>=13 else "medium"\n    return cleaned,confidence\n\n\n_extract_analyst_details_v15_base = _extract_analyst_details\n\ndef _extract_analyst_details(text):\n    out=_extract_analyst_details_v15_base(text)\n    src=re.sub(r"\\s+"," ",text or "").strip()\n\n    for d in out:\n        broker=d.get("broker") or ""\n\n        # Recover common "target price of $1,625" syntax.\n        if not d.get("newTarget"):\n            m=re.search(\n                r"(?:price target|target price|target)\\s+(?:of|to|at)\\s+\\$([\\d,.]+)",\n                src,re.I\n            )\n            if m:\n                d["newTarget"]=_fmt_target(m.group(1))\n\n        reason,confidence=_best_analyst_reason_v16(src,broker)\n        if reason:\n            translated=zh(reason)\n            d["reason"]=(translated or reason)[:420]\n            d["reasonConfidence"]=confidence\n        else:\n            d["reason"]=""\n            d["reasonConfidence"]="none"\n\n    return out\n\n\n'

def patch(src):
    src=replace_between(src,'def _analyst_reason_score_v15(sentence, broker="", idx=0, broker_idx=None):','def _analyst_details_summary(details):',ENGINE,'v16 reason engine')
    return src

def main():
    src=fetch_full()
    src=patch(src)
    compile(src,'updater.py','exec')
    for token in ['_best_analyst_reason_v16','_mechanical_only_v16','arguing that','target price of','reasonConfidence']:
        if token not in src: raise RuntimeError(f'v16 self-test missing: {token}')
    UPDATER.write_text(src,encoding='utf-8')
    print(f'Final updater installed: {len(src)} bytes, newsPatch=v16')
    code=compile(src,str(UPDATER),'exec')
    g={'__name__':'__main__','__file__':str(UPDATER),'__package__':None}
    exec(code,g,g)

if __name__=='__main__':
    main()
